syncActiveNavigation:
function syncActiveNavigation(section) {
              document.querySelectorAll('.nav-item[data-section],.mobile-more-option[data-section]').forEach(item => { const active = item.dataset.section === section; item.classList.toggle('active', active); if (item.hasAttribute('aria-current')) item.setAttribute('aria-current', active ? 'page' : 'false'); });
              const mobileMore = document.querySelector('[data-mobile-more]');
              const mobileOption = [...document.querySelectorAll('#mobileMoreMenu .mobile-more-option[data-section]')].find(item => item.dataset.section === section && !item.classList.contains('hidden'));
              mobileMore?.classList.toggle('active', Boolean(mobileOption));
              mobileMore?.setAttribute('aria-expanded', String(Boolean(mobileOption && !document.getElementById('mobileMoreMenu')?.classList.contains('hidden'))));
            }
